WITH content(slug, locale, lang, dir, align, subject, title, paras, cells, cta, text_body) AS (
VALUES
  ('invoice_issued', 'fa', 'fa', 'rtl', 'right', 'صورتحساب {invoice_number} صادر شد — {brand}', 'صورتحساب جدید صادر شد', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">صورتحساب تازه‌ای برای فضای کاری شما صادر شد. جزئیات آن را در ادامه می‌بینید.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">صدور صورتحساب باعث کسر خودکار از کیف پول نمی‌شود؛ مبلغ در تاریخ سررسید دریافت می‌شود.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">شماره صورتحساب</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">مبلغ</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">مهلت پرداخت</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{due_at}</td></tr>', 'مشاهده و پرداخت صورتحساب', 'صورتحساب {invoice_number} به مبلغ {amount} صادر شد. مهلت پرداخت: {due_at}. پرداخت: {action_url}'),
  ('invoice_reminder', 'fa', 'fa', 'rtl', 'right', 'یادآوری پرداخت صورتحساب {invoice_number} — {brand}', 'یادآوری پرداخت', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">سررسید صورتحساب شما نزدیک است.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">برای جلوگیری از وقفه در سرویس، پیش از تاریخ سررسید پرداخت کنید یا موجودی کیف پول را افزایش دهید.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">شماره صورتحساب</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">مبلغ</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">مهلت پرداخت</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{due_at}</td></tr>', 'پرداخت صورتحساب', 'مهلت پرداخت صورتحساب {invoice_number} به مبلغ {amount} تا {due_at} است. پرداخت: {action_url}'),
  ('invoice_due', 'fa', 'fa', 'rtl', 'right', 'امروز سررسید صورتحساب {invoice_number} — {brand}', 'امروز سررسید صورتحساب است', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">امروز آخرین روز پرداخت صورتحساب شماست.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">اگر پرداخت خودکار فعال باشد و موجودی کیف پول کافی باشد، مبلغ به‌صورت خودکار کسر می‌شود.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">شماره صورتحساب</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">مبلغ</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">مهلت پرداخت</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{due_at}</td></tr>', 'پرداخت صورتحساب', 'امروز سررسید صورتحساب {invoice_number} به مبلغ {amount} است. پرداخت: {action_url}'),
  ('invoice_past_due', 'fa', 'fa', 'rtl', 'right', 'صورتحساب {invoice_number} پرداخت نشده است — {brand}', 'صورتحساب معوق', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">صورتحساب شما در تاریخ سررسید پرداخت نشد.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">تا پایان مهلت نهایی فرصت دارید پرداخت کنید؛ پس از آن فضای کاری به پلن رایگان منتقل می‌شود. هیچ داده‌ای حذف نمی‌شود.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">شماره صورتحساب</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">مبلغ</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">مهلت نهایی</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{grace_ends_at}</td></tr>', 'پرداخت فوری', 'صورتحساب {invoice_number} به مبلغ {amount} پرداخت نشد. مهلت نهایی: {grace_ends_at}. پرداخت: {action_url}'),
  ('wallet_autopay_insufficient', 'fa', 'fa', 'rtl', 'right', 'موجودی کیف پول کافی نبود — {brand}', 'کسری موجودی کیف پول', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">پرداخت خودکار صورتحساب انجام نشد، چون موجودی کیف پول کافی نبود.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">لطفاً کیف پول را شارژ کنید یا صورتحساب را مستقیماً پرداخت کنید.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">شماره صورتحساب</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">مبلغ</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">مهلت پرداخت</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{due_at}</td></tr>', 'افزایش موجودی کیف پول', 'موجودی کیف پول برای پرداخت صورتحساب {invoice_number} به مبلغ {amount} کافی نبود. شارژ: {action_url}'),
  ('payment_received', 'fa', 'fa', 'rtl', 'right', 'پرداخت صورتحساب {invoice_number} تأیید شد — {brand}', 'پرداخت شما دریافت شد', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">پرداخت شما با موفقیت ثبت شد. از همراهی شما سپاسگزاریم.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">شماره صورتحساب</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">مبلغ</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{amount}</td></tr>', 'مشاهده رسید', 'پرداخت صورتحساب {invoice_number} به مبلغ {amount} با موفقیت ثبت شد.'),
  ('subscription_restored', 'fa', 'fa', 'rtl', 'right', 'اشتراک شما دوباره فعال شد — {brand}', 'اشتراک دوباره فعال شد', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">پرداخت شما دریافت شد و اشتراک از حالت بدهی خارج و فعال شد.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">تمام امکانات پلن شما هم‌اکنون در دسترس است.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">پلن</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{plan_name}</td></tr>', 'ورود به فضای کاری', 'پرداخت شما دریافت شد و اشتراک دوباره فعال شد.'),
  ('subscription_free_fallback', 'fa', 'fa', 'rtl', 'right', 'انتقال فضای کاری به پلن رایگان — {brand}', 'انتقال به پلن رایگان', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">به دلیل پرداخت نشدن صورتحساب در مهلت تعیین‌شده، فضای کاری شما به پلن رایگان منتقل شد.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">هیچ داده‌ای حذف نشده است و با ارتقای پلن، تمام امکانات دوباره در دسترس قرار می‌گیرد.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">پلن</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{plan_name}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">شماره صورتحساب</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:left;">{invoice_number}</td></tr>', 'ارتقای پلن', 'فضای کاری شما به پلن {plan_name} منتقل شد. ارتقا: {action_url}'),
  ('invoice_issued', 'en', 'en', 'ltr', 'left', 'Invoice {invoice_number} issued — {brand}', 'A new invoice is ready', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">A new invoice has been issued for your workspace. The details are below.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Issuing an invoice does not debit your wallet; payment is taken on the due date.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Invoice number</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Amount</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Due date</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{due_at}</td></tr>', 'View and pay invoice', 'Invoice {invoice_number} for {amount} was issued and is due on {due_at}. Pay: {action_url}'),
  ('invoice_reminder', 'en', 'en', 'ltr', 'left', 'Reminder: invoice {invoice_number} is due soon — {brand}', 'Payment reminder', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Your invoice is due soon.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Pay it or top up your wallet before the due date to avoid a service interruption.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Invoice number</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Amount</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Due date</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{due_at}</td></tr>', 'Pay invoice', 'Invoice {invoice_number} for {amount} is due on {due_at}. Pay: {action_url}'),
  ('invoice_due', 'en', 'en', 'ltr', 'left', 'Invoice {invoice_number} is due today — {brand}', 'Your invoice is due today', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Today is the last day to pay this invoice.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">If automatic payment is on and your wallet has enough balance, the amount is charged automatically.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Invoice number</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Amount</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Due date</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{due_at}</td></tr>', 'Pay invoice', 'Invoice {invoice_number} for {amount} is due today. Pay: {action_url}'),
  ('invoice_past_due', 'en', 'en', 'ltr', 'left', 'Invoice {invoice_number} is past due — {brand}', 'Invoice past due', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">This invoice was not paid on its due date.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">You can still pay until the end of the grace period; after that the workspace moves to the free plan. No data is deleted.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Invoice number</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Amount</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Grace period ends</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{grace_ends_at}</td></tr>', 'Pay now', 'Invoice {invoice_number} for {amount} is past due. Grace period ends {grace_ends_at}. Pay: {action_url}'),
  ('wallet_autopay_insufficient', 'en', 'en', 'ltr', 'left', 'Wallet balance was not enough — {brand}', 'Wallet balance insufficient', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Automatic payment failed because your wallet balance was not enough.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Top up your wallet or pay the invoice directly.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Invoice number</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Amount</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Due date</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{due_at}</td></tr>', 'Top up wallet', 'Wallet balance was insufficient for invoice {invoice_number} ({amount}). Top up: {action_url}'),
  ('payment_received', 'en', 'en', 'ltr', 'left', 'Payment received for invoice {invoice_number} — {brand}', 'Payment received', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">We have received your payment. Thank you.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Invoice number</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Amount</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{amount}</td></tr>', 'View receipt', 'We received your payment of {amount} for invoice {invoice_number}.'),
  ('subscription_restored', 'en', 'en', 'ltr', 'left', 'Your subscription is active again — {brand}', 'Subscription restored', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Your payment was received and the subscription is no longer past due.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">All features of your plan are available again.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Plan</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{plan_name}</td></tr>', 'Open workspace', 'Your payment was received and the subscription is active again.'),
  ('subscription_free_fallback', 'en', 'en', 'ltr', 'left', 'Your workspace moved to the free plan — {brand}', 'Moved to the free plan', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Because the invoice was not paid within the grace period, your workspace moved to the free plan.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">No data has been deleted, and upgrading restores full service.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Plan</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{plan_name}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Invoice number</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{invoice_number}</td></tr>', 'Upgrade plan', 'Your workspace moved to the {plan_name} plan. Upgrade: {action_url}'),
  ('invoice_issued', 'tr', 'tr', 'ltr', 'left', '{invoice_number} numaralı fatura oluşturuldu — {brand}', 'Yeni faturanız hazır', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Çalışma alanınız için yeni bir fatura oluşturuldu. Ayrıntılar aşağıdadır.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Fatura oluşturulması cüzdanınızdan otomatik tahsilat yapmaz; ödeme vade tarihinde alınır.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Fatura numarası</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Tutar</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Son ödeme tarihi</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{due_at}</td></tr>', 'Faturayı görüntüle ve öde', '{invoice_number} numaralı {amount} tutarındaki fatura oluşturuldu. Vade: {due_at}. Ödeme: {action_url}'),
  ('invoice_reminder', 'tr', 'tr', 'ltr', 'left', 'Hatırlatma: {invoice_number} numaralı faturanın vadesi yaklaşıyor — {brand}', 'Ödeme hatırlatması', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Faturanızın vadesi yaklaşıyor.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Hizmet kesintisini önlemek için vadeden önce ödeyin veya cüzdanınıza bakiye yükleyin.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Fatura numarası</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Tutar</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Son ödeme tarihi</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{due_at}</td></tr>', 'Faturayı öde', '{invoice_number} numaralı {amount} tutarındaki faturanın vadesi {due_at}. Ödeme: {action_url}'),
  ('invoice_due', 'tr', 'tr', 'ltr', 'left', '{invoice_number} numaralı faturanın vadesi bugün — {brand}', 'Faturanızın vadesi bugün', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Bu faturayı ödemek için son gün bugün.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Otomatik ödeme açıksa ve cüzdan bakiyeniz yeterliyse tutar otomatik tahsil edilir.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Fatura numarası</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Tutar</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Son ödeme tarihi</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{due_at}</td></tr>', 'Faturayı öde', '{invoice_number} numaralı {amount} tutarındaki faturanın vadesi bugün. Ödeme: {action_url}'),
  ('invoice_past_due', 'tr', 'tr', 'ltr', 'left', '{invoice_number} numaralı fatura gecikmiş durumda — {brand}', 'Gecikmiş fatura', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Bu fatura vadesinde ödenmedi.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Ek süre sonuna kadar ödeyebilirsiniz; sonrasında çalışma alanı ücretsiz plana geçer. Hiçbir veri silinmez.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Fatura numarası</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Tutar</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Ek süre bitişi</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{grace_ends_at}</td></tr>', 'Hemen öde', '{invoice_number} numaralı {amount} tutarındaki fatura gecikti. Ek süre bitişi: {grace_ends_at}. Ödeme: {action_url}'),
  ('wallet_autopay_insufficient', 'tr', 'tr', 'ltr', 'left', 'Cüzdan bakiyesi yetersiz — {brand}', 'Cüzdan bakiyesi yetersiz', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Cüzdan bakiyeniz yeterli olmadığı için otomatik ödeme yapılamadı.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Lütfen bakiye yükleyin veya faturayı doğrudan ödeyin.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Fatura numarası</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Tutar</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{amount}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Son ödeme tarihi</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{due_at}</td></tr>', 'Cüzdana bakiye yükle', '{invoice_number} numaralı fatura ({amount}) için cüzdan bakiyesi yetersizdi. Yükleme: {action_url}'),
  ('payment_received', 'tr', 'tr', 'ltr', 'left', '{invoice_number} numaralı fatura için ödeme alındı — {brand}', 'Ödemeniz alındı', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Ödemeniz başarıyla alındı. Teşekkür ederiz.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Fatura numarası</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{invoice_number}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Tutar</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{amount}</td></tr>', 'Makbuzu görüntüle', '{invoice_number} numaralı fatura için {amount} tutarındaki ödemeniz alındı.'),
  ('subscription_restored', 'tr', 'tr', 'ltr', 'left', 'Aboneliğiniz yeniden etkin — {brand}', 'Abonelik yeniden etkin', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Ödemeniz alındı ve aboneliğiniz gecikmiş durumdan çıkarıldı.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Planınızın tüm özellikleri yeniden kullanılabilir.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Plan</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{plan_name}</td></tr>', 'Çalışma alanını aç', 'Ödemeniz alındı ve aboneliğiniz yeniden etkin.'),
  ('subscription_free_fallback', 'tr', 'tr', 'ltr', 'left', 'Çalışma alanınız ücretsiz plana geçti — {brand}', 'Ücretsiz plana geçiş', '<p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Fatura ek süre içinde ödenmediği için çalışma alanınız ücretsiz plana geçti.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Hiçbir veri silinmedi; planı yükselttiğinizde hizmet geri gelir.</p>', '<tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Plan</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{plan_name}</td></tr><tr><td style="padding:8px 0;color:#64748b;font-size:13px;">Fatura numarası</td><td style="padding:8px 0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{invoice_number}</td></tr>', 'Planı yükselt', 'Çalışma alanınız {plan_name} planına geçti. Yükseltme: {action_url}')
), rendered AS (
  SELECT slug, locale, subject, text_body,
    '<!DOCTYPE html><html lang="' || lang || '" dir="' || dir || '"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>' || title || '</title></head>'
    || '<body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;-webkit-font-smoothing:antialiased;">'
    || '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;">'
    || '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;">'
    || '<tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;letter-spacing:-0.3px;">{brand}</h1></td></tr>'
    || '<tr><td style="padding:40px;text-align:' || align || ';"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">' || title || '</h2>' || paras || '</td></tr>'
    || '<tr><td style="padding:0 40px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:8px 16px;text-align:' || align || ';">' || cells || '</table></td></tr>'
    || '<tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">' || cta || '</a></td></tr>'
    || '<tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr>'
    || '</table></td></tr></table></body></html>' AS html_body
  FROM content
)
INSERT INTO public.email_templates (workspace_id, slug, locale, subject, html_body, text_body, is_active)
SELECT NULL, r.slug, r.locale, r.subject, r.html_body, r.text_body, true
FROM rendered r
WHERE NOT EXISTS (
  SELECT 1 FROM public.email_templates e
  WHERE e.workspace_id IS NULL AND e.slug = r.slug AND e.locale = r.locale
);